    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is the general legal rule for medical treatment of a non-emancipated minor?', '["The minor provides their own consent", "The parents (or legal guardians) provide informed consent on behalf of the minor", "The doctor decides", "The school decides"]', 1, 'In the eyes of the law, non-emancipated minors are generally considered to lack the legal capacity to consent for themselves.'),
    (v_topic_id, 'Which legal doctrine allows a 16-year-old who is married, in the military, or self-supporting and living independently to provide their own informed consent?', '["Mature Minor Doctrine", "Emancipation", "Parens Patriae", "Proxy Consent"]', 1, 'Emancipated minors have attained legal adult status for the purposes of medical decision-making.'),
    (v_topic_id, 'In many US states, the "Mature Minor Doctrine" allows a physician to accept a minor''s consent if:', '["The minor is over 14 and deemed by the physician to have the maturity to understand the risks and benefits of the specific decision", "The minor has a high GPA", "The minor is taller than the doctor", "None of the above"]', 0, 'The Mature Minor Doctrine is a common-law or statutory rule that recognizes that some older minors have adult-level decision-making capacity.'),
    (v_topic_id, 'A 15-year-old girl seeks treatment for a sexually transmitted infection (STI). In most US states, the physician should:', '["Refuse to treat without parental consent", "Treat the minor and keep the visit confidential from the parents (as allowed by state law for sensitive services)", "Call the parents immediately", "Notify the school principal"]', 1, 'Most states have "Sensitive Service" laws that allow minors to consent to STI testing/treatment, contraception, and prenatal care without parental involvement to encourage them to seek care.'),
    (v_topic_id, 'Parents refuse a life-saving blood transfusion for their 8-year-old child based on religious beliefs. The physician should:', '["Respect the parents'' religious freedom", "Seek an emergency court order to treat the child (under the doctrine of Parens Patriae)", "Wait for the child to turn 18", "None of the above"]', 1, 'While adults can refuse life-saving care for themselves, they cannot refuse it for their minor children. The state acts as the "parent of the nation" (Parens Patriae) to protect the child''s life.'),
    (v_topic_id, 'A 17-year-old boy refuses a non-urgent, elective cosmetic surgery that his parents have consented to. The physician should:', '["Perform the surgery anyway", "Respect the minor''s refusal (withhold treatment) as he is near the age of majority and his ''Assent'' is ethically necessary for a non-essential procedure", "Call the police", "None of the above"]', 1, 'For non-urgent, non-essential care, the minor''s objection (lack of assent) should generally be respected.'),
    (v_topic_id, 'Which of the following services can a minor usually consent to WITHOUT parental notification in most jurisdictions?', '["Treatment for a broken leg", "Alcohol or drug abuse counseling", "Appendectomy", "Routine dental cleaning"]', 1, 'Mental health and substance abuse services are often "Sensitive Services" that minors can access independently.'),
    (v_topic_id, 'A 16-year-old girl is pregnant and wants an abortion. In a state with a "Parental Consent" law, she can avoid telling her parents by:', '["Getting a letter from a teacher", "Seeking a ''Judicial Bypass'' from a judge", "Moving to another country", "None of the above"]', 1, 'The US Supreme Court requires that states with parental involvement laws for abortion provide an alternative path (Judicial Bypass) for mature minors or those for whom notification would be harmful.'),
    (v_topic_id, 'Divorced parents have "Joint Legal Custody" of a child. One parent consents to a vaccination, the other refuses. The physician should:', '["Follow the parent who said ''Yes", "Work with the parents to reach a consensus; if they cannot, the court may need to decide, though usually, life-saving or standard-of-care preventative measures are favored", "Give half the dose", "None of the above"]', 1, 'Disagreements between joint custodians are difficult. The physician should avoid taking sides and encourage mediation.'),
    (v_topic_id, 'A "Mature Minor" in an emergency should be treated:', '["Only with parental consent", "Under the ''Emergency Exception'' (Implied Consent), just like an adult", "Only after a psych eval", "None of the above"]', 1, 'Life-threatening emergencies override the need for parental consent.'),
    (v_topic_id, 'A 14-year-old boy is brought in by his grandmother, who does not have legal guardianship. The boy needs a routine physical. The physician should:', '["Proceed with the physical", "Obtain consent from the legal guardian (parent) via phone or written authorization before proceeding with non-emergent care", "Ask the neighbor", "None of the above"]', 1, 'Biological relationship (like being a grandparent) does not automatically grant legal authority to provide consent.'),
    (v_topic_id, 'Which of the following describes "Parens Patriae"?', '["The right of parents to choose a school", "The state''s authority to protect individuals (like children) who cannot protect themselves", "A type of insurance", "None of the above"]', 1, 'This doctrine is the basis for state intervention in cases of child abuse or medical neglect.'),
    (v_topic_id, 'A 17-year-old girl wants to be an organ donor when she gets her driver''s license. In many states:', '["She cannot choose until she is 18", "She can sign the donor card, but her parents can overrule her decision if she dies while still a minor", "Her choice is legally binding and irrevocable", "None of the above"]', 1, 'While minors can express their wishes, parents usually have the final say in organ donation for a deceased minor.'),
    (v_topic_id, 'Which principle is most directly involved when a minor provides "Assent"?', '["Justice", "Respect for Autonomy (developing)", "Veracity", "None of the above"]', 1, 'Assent honors the child''s growing capacity to participate in their own life decisions.'),
    (v_topic_id, 'A parent wants to enroll their child in a "Non-therapeutic" research study (one that offers no direct benefit to the child). This is:', '["Always illegal", "Permissible only if the risk is ''Minimal'' and the child does not object (withhold assent)", "Always legal if the parent says yes", "None of the above"]', 1, 'Stricter ethical rules apply to research on children, especially when there is no direct clinical benefit.'),
    (v_topic_id, 'Can a minor be an "Emancipated Minor" if they are still living at home but are married?', '["No, you must move out", "Yes, in many states, marriage automatically emancipates a minor", "Only if they have a job", "None of the above"]', 1, 'The specific criteria for emancipation vary by state but marriage is a common trigger.'),
    (v_topic_id, 'A 16-year-old boy has a "Living Will" that he wrote himself. Is it legally binding?', '["Yes", "No, minors generally cannot create legally binding advance directives, though the document may be used as evidence of their values", "Only if it is notarized", "None of the above"]', 1, 'Advance directives are legal documents that require the signer to have attained the age of majority (usually 18).'),
    (v_topic_id, 'A physician believes that a parent''s refusal of a non-life-saving treatment (e.g., refusing to fix a clubfoot) constitutes "Medical Neglect." They should:', '["Ignore it", "Report the case to Child Protective Services (CPS) for investigation", "Fix the foot anyway", "None of the above"]', 1, 'Reporting is mandatory if the refusal of care is likely to cause significant permanent disability or suffering to the child.'),
    (v_topic_id, 'A 12-year-old girl is dying of cancer and says: "I''m tired of the chemo, I want to stop." Her parents want to continue. The physician should:', '["Always listen to the parents", "Involve a pediatric palliative care or ethics team to facilitate a discussion that honors the child''s experience while working with the parents", "Stop the chemo immediately", "None of the above"]', 1, 'The "Best Interests" of a terminally ill child often include respecting their desire to stop suffering, but it requires careful family mediation.'),
    (v_topic_id, 'Which of the following is true about "Confidentiality" for minors in sensitive service cases?', '["It is absolute", "It can be broken if the physician believes the minor is at high risk of self-harm or if mandatory reporting (like abuse) is triggered", "It only applies to girls", "None of the above"]', 1, 'Confidentiality is a strong tool to encourage care, but safety overrides it.'),
    (v_topic_id, 'A parent requests the medical records of their 17-year-old child. According to HIPAA:', '["The parent always has access", "If the minor consented to the care on their own (under a state sensitive service law), the parent may NOT have a right to those specific records without the minor''s consent", "Records are only for the doctor", "None of the above"]', 1, 'Privacy rights for minors often track their consent rights.'),
    (v_topic_id, 'A 15-year-old boy is in a coma. His divorced parents (with joint custody) disagree on removing the ventilator. What is the next step?', '["Flip a coin", "Consult the ethics committee and potentially the court, as the parents are equal legal surrogates and cannot agree on a life-altering decision", "Listen to the mother", "None of the above"]', 1, 'Deadlock between equal surrogates often requires judicial intervention if mediation fails.'),
    (v_topic_id, 'Can a minor be an "Organ Donor" for a sibling (e.g., donating bone marrow)?', '["No, minors can''t donate", "Yes, but it requires parental consent, an independent review (e.g., by a court or committee) to ensure it is in the best interest of the donor minor, and the minor''s assent", "Yes, if the doctor says so", "None of the above"]', 1, 'Protecting the donor minor from exploitation is the priority.'),
    (v_topic_id, 'A 17-year-old seeks a vaccination. Their parents are "Anti-vaxxers." Can the minor consent for themselves?', '["No, never", "In some states (like Oregon or Alabama), older minors have specific rights to consent to vaccinations without parental permission", "Only if they pay for it", "None of the above"]', 1, 'State laws on minor consent for vaccination are evolving and vary significantly.'),
    (v_topic_id, 'Which of the following is a "Medical Order" that parents *can* sign for a terminally ill child?', '["A Last Will", "A pediatric DNR/DNAR (with the assent of the child if appropriate)", "A marriage license", "None of the above"]', 1, 'Parents can make end-of-life decisions for their children, including DNR status.'),
    (v_topic_id, 'If a minor is "Abandoned" by their parents, who provides consent for their care?', '["The police", "A court-appointed guardian or the state child welfare agency", "The neighbor", "None of the above"]', 1, 'Wards of the state have specific legal mechanisms for consent.'),
    (v_topic_id, 'A parent wants their 13-year-old daughter to have a "Hysterectomy" because she has a developmental disability and they don''t want her to have periods. The physician should:', '["Do it immediately", "Exercise extreme caution, as the sterilization of minors with disabilities is legally and ethically restricted and often requires a specific court order", "Do it if the insurance pays", "None of the above"]', 1, 'Sterilization of minors is a high-threshold issue that involves fundamental reproductive rights.'),
    (v_topic_id, 'The "Baby Doe" rules were created to:', '["Protect the privacy of babies", "Prevent the withholding of life-saving medical treatment from infants with disabilities solely because of those disabilities", "Encourage adoption", "None of the above"]', 1, 'These rules emphasize that disability is not a reason to withhold standard, life-saving care from an infant.'),
    (v_topic_id, 'A 16-year-old girl is found to be "Self-harming" during a confidential STI visit. Should the physician tell the parents?', '["No, it''s confidential", "Yes, the duty to protect the minor from immediate harm overrides the confidentiality of the STI visit", "Only if she says it''s okay", "None of the above"]', 1, 'Safety is the boundary of confidentiality.'),
    (v_topic_id, 'Which of the following is true about "Step-parents" and consent?', '["They always have the same rights as biological parents", "They generally do NOT have legal consent authority unless they have formally adopted the child or have been given specific power of attorney by a legal parent", "They can only consent to emergencies", "None of the above"]', 1, 'Legal status, not just household relationship, determines consent authority.'),
    (v_topic_id, 'A minor is "Incarcerated." Who provides consent for their medical care?', '["The warden", "The parents (usually) or the state agency responsible for the minor''s custody, depending on the state law and the type of care", "The other inmates", "None of the above"]', 1, 'Rights of parents are often preserved even when a minor is in the juvenile justice system.'),
    (v_topic_id, 'Can a 17-year-old "Emancipated Minor" refuse a life-saving treatment?', '["No, they are still kids", "Yes, they have the same legal rights as an adult to refuse any medical treatment", "Only if their parents agree", "None of the above"]', 1, 'Emancipation is a "full-rights" status.'),
    (v_topic_id, 'A parent wants to know the results of their 16-year-old son''s "Drug Test" performed during a sports physical. The physician should:', '["Give the results immediately", "In many states, the physician should obtain the minor''s consent to share this information, especially if the minor was promised confidentiality to encourage honesty", "Lie and say it was negative", "None of the above"]', 1, 'Confidentiality for substance use is a common minor right.'),
    (v_topic_id, 'A "Mature Minor" wants a tattoo. Does medical law apply?', '["Yes", "No, tattooing is generally governed by different age-of-consent laws than medical care", "Only if it''s a medical tattoo", "None of the above"]', 1, 'Medical consent laws are specific to healthcare.'),
    (v_topic_id, 'A 10-year-old boy is "Assenting" to a flu shot. He is crying but says "Okay." This is:', '["Coercion", "A valid assent, as he understands the need even if he is afraid of the needle", "Incompetence", "None of the above"]', 1, 'Assent doesn''t mean the child has to be happy about it; it means they agree to go along with it.'),
    (v_topic_id, 'If a minor is "Homeless and Unaccompanied" (Runaway), many states allow them to:', '["Get a job", "Consent for their own basic medical and dental care", "Sue their parents", "None of the above"]', 1, 'Special laws exist to prevent barriers to care for vulnerable, unaccompanied youth.'),
    (v_topic_id, 'A parent asks a physician to "Fix" their 17-year-old son''s sexual orientation through therapy. The physician should:', '["Try to help", "Explain that ''Conversion Therapy'' is unethical, widely considered harmful, and illegal for minors in many jurisdictions", "Charge a high fee", "None of the above"]', 1, 'Conversion therapy is a violation of the "Non-maleficence" principle.'),
    (v_topic_id, 'Which of the following is true about "Newborn Screening" tests?', '["They require specific parental consent", "They are mandated by the state (opt-out or mandatory) for public health reasons, though parents can sometimes refuse based on religious grounds", "They are optional", "None of the above"]', 1, 'Newborn screening (for PKU, etc.) is a state-level public health mandate.'),
    (v_topic_id, 'A 17-year-old boy wants to join a "Phase 1" clinical trial for a drug that has never been tested in humans. Can his parents consent for him?', '["Yes, parents can do anything", "Ethically, this is highly problematic as it involves ''Greater than Minimal Risk'' with no direct benefit; IRB approval and the minor''s strong assent would be required", "Only if he is paid", "None of the above"]', 1, 'Research on minors is strictly regulated based on the risk-benefit ratio.'),
    (v_topic_id, 'A parent wants to see the "Psychotherapy Notes" of their 15-year-old child. The therapist:', '["Must provide them", "Can refuse if they believe sharing the notes would harm the therapeutic relationship or the minor, and if state law supports minor privacy in mental health", "Must burn the notes", "None of the above"]', 1, 'Mental health notes have the highest level of privacy protection for minors.'),
    (v_topic_id, 'Which of the following is an "Adolescent" right in many states?', '["The right to drive at 10", "The right to consent to ''Sensitive Services'' (Sexual/Mental Health/Substance Use)", "The right to skip school", "None of the above"]', 1, 'These rights are designed to improve public health outcomes.'),
    (v_topic_id, 'A 16-year-old boy is "Assenting" to an organ donation for his father. Who makes the final decision?', '["The boy", "The mother (legal guardian), the hospital ethics committee, and often a court, to ensure the boy is not being coerced", "The father", "None of the above"]', 1, 'Donation *from* a minor requires multiple layers of protection.'),
    (v_topic_id, 'If a minor "Refuses" a life-saving treatment (like chemo) that has a very high success rate, the physician must:', '["Stop the treatment", "Work with the family and potentially seek a court order to continue treatment, as the ''Parens Patriae'' duty to protect the child''s life overrides their developing autonomy in high-stakes cases", "Call the police", "None of the above"]', 1, 'Life-saving care with a good prognosis is almost always mandated over a minor''s objection.'),
    (v_topic_id, 'Can a 17-year-old "Mature Minor" sign a DNR order for themselves?', '["Yes", "Generally no, as it is a legal medical order that requires an adult signer (Parent or Physician), though the minor''s wishes are a critical part of the discussion", "Only if they are married", "None of the above"]', 1, 'DNR status for minors involves a combination of parental authority and the child''s assent.'),
    (v_topic_id, 'A 12-year-old girl wants to start "Gender-Affirming Hormones." In many states, this requires:', '["Only her consent", "Consent from BOTH parents (usually) and an extensive multidisciplinary evaluation, with legal requirements varying by state", "Only the doctor''s consent", "None of the above"]', 1, 'Care for gender dysphoria in minors is currently a highly regulated and legally complex area.'),
    (v_topic_id, 'A parent wants to know if their 15-year-old daughter is "Sexually Active" after a pelvic exam. The physician should:', '["Tell the parent immediately", "Maintain the minor''s confidentiality (if she was promised it) but encourage her to have an honest conversation with her parent", "Lie", "None of the above"]', 1, 'Protecting the "safe space" for adolescent healthcare is essential for public health.'),
    (v_topic_id, 'Which of the following is true regarding "Foster Parents" and consent?', '["They have the same rights as biological parents", "Their authority to consent varies significantly by state and the specific terms of the foster care agreement, often requiring coordination with a state social worker", "They have no rights", "None of the above"]', 1, 'Foster care consent is a three-way interaction between the foster parent, the state, and the biological parent (if rights aren''t terminated).'),
    (v_topic_id, 'A 17-year-old boy is "Emancipated" and wants a vasectomy. Should the physician perform it?', '["No, he might regret it", "The physician should assess the minor''s capacity and reasoning just like an adult, but may still exercise clinical judgment about the appropriateness of permanent sterilization at that age", "Yes, immediately", "None of the above"]', 1, 'Legal right does not equal a medical mandate; clinical judgment still applies.'),
    (v_topic_id, 'A parent is "Impaired" (e.g., drunk) while trying to consent for their child''s non-urgent surgery. The physician should:', '["Accept the consent", "Decline to proceed and wait until the parent is sober or a sober legal co-guardian is available", "Call the police", "None of the above"]', 1, 'An impaired parent lacks the capacity to provide informed consent for their child.'),
    (v_topic_id, 'The "Best Interest of the Child" standard in medicine means:', '["The parent chooses everything", "The decision is based on what will maximize the child''s long-term health, development, and well-being", "The child chooses everything", "None of the above"]', 1, 'This is the objective standard used when the patient cannot speak for themselves.');
